class Solution {
    void collect(TreeNode* node, std::unordered_set<int>& vals) {
        if (!node) return;
        vals.insert(node->val);
        collect(node->left, vals);
        collect(node->right, vals);
    }
    bool check(TreeNode* node, const std::unordered_set<int>& vals, int target) {
        if (!node) return false;
        if (vals.count(target - node->val)) return true;
        return check(node->left, vals, target) || check(node->right, vals, target);
    }
