        return check(root2, vals, target);
    }
};

class Solution {
    void collect(TreeNode node, java.util.Set<Integer> vals) {
        if (node == null) return;
        vals.add(node.val);
        collect(node.left, vals);
        collect(node.right, vals);
    }
    boolean check(TreeNode node, java.util.Set<Integer> vals, int target) {
        if (node == null) return false;
        if (vals.contains(target - node.val)) return true;
        return check(node.left, vals, target) || check(node.right, vals, target);
    }
    public boolean twoSumBSTs(TreeNode root1, TreeNode root2, int target) {
        java.util.Set<Integer> vals = new java.util.HashSet<>();
        collect(root1, vals);
        return check(root2, vals, target);
    }
}

